<?php
require_once '../../includes/auth_check.php';
requireAdmin();
require_once '../../config/database.php';
$filter=$_GET['filter']??'';$search=trim($_GET['search']??'');$page=max(1,intval($_GET['page']??1));$limit=10;$offset=($page-1)*$limit;
$where='1=1';$params=[];$types='';
if(in_array($filter,['pending','selesai'],true))$where.=" AND t.status='$filter'";
if($search){$where.=' AND (t.kode_transaksi LIKE ? OR u.nama LIKE ? OR u.no_hp LIKE ?)';$like="%$search%";$params=[$like,$like,$like];$types='sss';}
$count=$conn->prepare("SELECT COUNT(*) c FROM everwear_transaksi t JOIN users u ON u.id=t.customer_id WHERE $where");if($types)$count->bind_param($types,...$params);$count->execute();$totalRows=$count->get_result()->fetch_assoc()['c'];$totalPages=ceil($totalRows/$limit);
$stmt=$conn->prepare("SELECT t.*,u.nama customer_nama,u.no_hp,a.nama admin_nama FROM everwear_transaksi t JOIN users u ON u.id=t.customer_id LEFT JOIN users a ON a.id=t.admin_id WHERE $where ORDER BY CASE WHEN t.status='pending' THEN 0 ELSE 1 END,t.created_at DESC LIMIT ? OFFSET ?");$p=$params;$p[]=$limit;$p[]=$offset;$bind=$types.'ii';$stmt->bind_param($bind,...$p);$stmt->execute();$list=$stmt->get_result();
$pending=$conn->query("SELECT COUNT(*) c FROM everwear_transaksi WHERE status='pending'")->fetch_assoc()['c'];
?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Donasi Masuk — Everwear</title><link rel="stylesheet" href="../../assets/css/output.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&family=Be+Vietnam+Pro:wght@400;500;600;700&display=swap" rel="stylesheet"><style>.filter-tab{padding:.4rem .9rem;border-radius:999px;font-size:.8rem;font-weight:600;border:1.5px solid var(--color-border);background:#fff;text-decoration:none;color:var(--color-ink-muted);display:inline-flex;gap:.35rem;align-items:center}.filter-tab.active{background:var(--color-primary-container);border-color:var(--color-primary-container);color:var(--color-primary-dark)}.filter-tabs{display:flex;gap:.5rem;flex-wrap:wrap}</style></head><body><div class="layout"><?php include '../../includes/sidebar_admin_everwear.php'; ?><main class="main"><div class="topbar"><div class="topbar-left"><button class="hamburger" onclick="toggleSidebar()"><i class="fa-solid fa-bars"></i></button><div><h1>Donasi Masuk</h1><p>Periksa dan verifikasi setor pakaian Everwear</p></div></div><div class="topbar-right"><?php include '../../includes/notif_admin.php'; ?></div></div><div class="content">
<div class="card mb-4"><div class="card-body filter-search-wrap"><div class="filter-tabs"><a href="?" class="filter-tab <?=!$filter?'active':''?>"><i class="fa-solid fa-list"></i> Semua</a><a href="?filter=pending" class="filter-tab <?=$filter==='pending'?'active':''?>"><i class="fa-solid fa-clock"></i> Pending <?php if($pending):?><span class="badge badge-orange"><?=$pending?></span><?php endif;?></a><a href="?filter=selesai" class="filter-tab <?=$filter==='selesai'?'active':''?>"><i class="fa-solid fa-check"></i> Selesai</a></div><form method="GET" class="search-form-inline"><input type="hidden" name="filter" value="<?=htmlspecialchars($filter)?>"><div class="search-bar"><i class="fa-solid fa-magnifying-glass"></i><input name="search" value="<?=htmlspecialchars($search)?>" placeholder="Cari kode atau customer..."></div></form></div></div>
<div class="card"><div class="card-header"><h3>Daftar Donasi</h3></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Kode</th><th>Donatur</th><th>Jadwal Datang</th><th>Jumlah</th><th>Poin</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$list->num_rows):?><tr><td colspan="8"><div class="empty-state"><p>Belum ada donasi</p></div></td></tr><?php else:$no=$offset+1;while($r=$list->fetch_assoc()):$pendingRow=$r['status']==='pending';?><tr <?=$pendingRow?'style="background:#FFF8E1"':''?>><td><?=$no++?></td><td><span class="badge <?=$pendingRow?'badge-orange':'badge-green'?>"><?=htmlspecialchars($r['kode_transaksi'])?></span><div class="text-muted text-small">Layak: <?=intval($r['pcs_layak'])?> pcs · Recycle: <?=intval($r['pcs_recycle'])?> pcs</div></td><td><div class="font-semibold"><?=htmlspecialchars($r['customer_nama'])?></div><div class="text-muted text-small"><?=htmlspecialchars($r['no_hp']?:'-')?></div></td><td><?=!empty($r['jadwal_setor'])?date('d M Y H:i',strtotime($r['jadwal_setor'])):'-'?></td><td><?=$r['jumlah_pcs']?> pcs · <?=number_format($r['berat_kg'],2)?> kg</td><td><?=$r['poin_diperoleh']?'<strong>+'.number_format($r['poin_diperoleh']).'</strong>':'-'?></td><td><span class="badge badge-<?=$r['status']==='selesai'?'green':($r['status']==='pending'?'orange':'blue')?>"><?=ucfirst($r['status'])?></span></td><td><?php if($pendingRow):?><button class="btn btn-primary btn-sm" onclick="periksa(<?=$r['id']?>,<?=intval($r['pcs_layak'])?>,<?=intval($r['pcs_recycle'])?>,<?=$r['berat_kg']?>,'<?=htmlspecialchars($r['kode_transaksi'],ENT_QUOTES)?>','<?=htmlspecialchars($r['customer_nama'],ENT_QUOTES)?>','<?=htmlspecialchars($r['no_hp'] ?? '-',ENT_QUOTES)?>','<?=htmlspecialchars($r['jadwal_setor'] ? date('d M Y H:i', strtotime($r['jadwal_setor'])) : '-',ENT_QUOTES)?>')"><i class="fa-solid fa-weight-scale"></i> Periksa</button><button class="btn btn-danger btn-sm" onclick="batalkanDonasi(<?=$r['id']?>)"><i class="fa-solid fa-xmark"></i></button><?php else:?><button class="btn btn-info btn-sm" onclick="detail('<?=htmlspecialchars($r['kode_transaksi'],ENT_QUOTES)?>','<?=$r['kategori_pakaian']?>','<?=$r['jumlah_pcs']?>','<?=$r['berat_kg']?>','<?=$r['poin_diperoleh']?>','<?=htmlspecialchars($r['verified_at'] ? date('d M Y H:i', strtotime($r['verified_at'])) : '', ENT_QUOTES)?>','<?=htmlspecialchars($r['admin_nama'] ?? '', ENT_QUOTES)?>')"><i class="fa-solid fa-eye"></i></button><?php endif;?></td></tr><?php endwhile;endif;?></tbody></table></div></div></div></main></div>
<div class="modal-overlay" id="modalPeriksa"><div class="modal" style="max-width:520px"><div class="modal-header"><h3><i class="fa-solid fa-weight-scale" style="color:var(--primary)"></i> Periksa Donasi</h3><button class="modal-close" onclick="tutup()"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body"><input type="hidden" id="trxId"><div id="kodeInfo" style="background:var(--primary-light);padding:.75rem;border-radius:10px;margin-bottom:1rem"></div><div id="customerInfo" style="background:var(--bg-light);padding:.75rem;border-radius:10px;margin-bottom:1rem;font-size:.85rem"></div><div class="form-group"><label class="form-label">Layak Pakai (pcs)</label><input class="form-control" id="pcsLayak" type="number" min="0" oninput="previewPoin()"></div><div class="form-group"><label class="form-label">Tidak Layak/Recycle (pcs)</label><input class="form-control" id="pcsRecycle" type="number" min="0" oninput="previewPoin()"></div><div class="form-group"><label class="form-label">Berat Aktual (kg)</label><input class="form-control" id="berat" type="number" min="0.1" step="0.1" oninput="previewPoin()"><div class="text-muted text-small">Poin (layak & recycle): 10 poin/kg</div></div><div style="background:var(--primary-light);padding:1rem;border-radius:10px;text-align:center"><div class="text-muted text-small">Poin yang akan diberikan</div><strong id="preview" style="font-size:1.4rem;color:var(--primary-dark)">0 poin</strong></div><div class="form-group" style="margin-top:1rem"><label class="form-label">Catatan Admin (opsional)</label><textarea class="form-control" id="catatan" rows="2"></textarea></div></div><div class="modal-footer"><button class="btn btn-ghost" onclick="tutup()">Batal</button><button class="btn btn-primary" onclick="verifikasi()"><i class="fa-solid fa-check"></i> Verifikasi Selesai</button></div></div></div>
<script>function toggleSidebar(){document.getElementById('sidebar').classList.toggle('open');document.getElementById('sidebarOverlay').classList.toggle('open')}function closeSidebar(){document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebarOverlay').classList.remove('open')}function periksa(id,layak,recycle,berat,kode,customer,noHp,jadwal){document.getElementById('trxId').value=id;document.getElementById('pcsLayak').value=layak;document.getElementById('pcsRecycle').value=recycle;document.getElementById('berat').value=berat;document.getElementById('kodeInfo').textContent='Kode donasi: '+kode;document.getElementById('customerInfo').innerHTML='<b>Customer:</b> '+customer+' ('+noHp+')<br><b>Rencana Datang:</b> '+jadwal+' WIB';document.getElementById('catatan').value='';previewPoin();document.getElementById('modalPeriksa').classList.add('open')}function tutup(){document.getElementById('modalPeriksa').classList.remove('open')}function previewPoin(){document.getElementById('preview').textContent=Math.max(1,Math.round(parseFloat(document.getElementById('berat').value||0)*10))+' poin'}function verifikasi(){const transaksi_id=+document.getElementById('trxId').value,pcs_layak=+document.getElementById('pcsLayak').value||0,pcs_recycle=+document.getElementById('pcsRecycle').value||0,berat_kg=+document.getElementById('berat').value,catatan_admin=document.getElementById('catatan').value.trim();if((pcs_layak<0||pcs_recycle<0)||(pcs_layak===0&&pcs_recycle===0)||!berat_kg){Swal.fire('Data belum lengkap','','warning');return}fetch('<?=BASE_URL?>/api/verifikasi-everwear.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'verifikasi',transaksi_id,pcs_layak,pcs_recycle,berat_kg,catatan_admin})}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(r=>{if(r.success)Swal.fire('Berhasil','+'+r.poin+' poin diberikan','success').then(()=>location.reload());else Swal.fire('Gagal',r.message,'error')}).catch(e=>Swal.fire('Gagal',e.message,'error'))}function batalkanDonasi(id){Swal.fire({title:'Batalkan donasi?',text:'Donasi pending akan dibatalkan.',icon:'warning',showCancelButton:true,confirmButtonText:'Ya, batalkan',cancelButtonText:'Tidak',confirmButtonColor:'#d33'}).then(r=>{if(!r.isConfirmed)return;fetch('<?=BASE_URL?>/api/everwear-setor.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'batalkan',id})}).then(r=>r.json()).then(r=>r.success?Swal.fire('Berhasil','Donasi dibatalkan.','success').then(()=>location.reload()):Swal.fire('Gagal',r.message,'error')).catch(e=>Swal.fire('Gagal',e.message,'error'))})}function detail(k,kategori,pcs,berat,poin,verifiedAt,adminNama){Swal.fire({title:k,html:`Kategori: <b>${kategori=='campuran'?'Campuran':(kategori==='layak_pakai'?'Layak Pakai':'Tekstil Recycle')}</b><br>${pcs} pcs · ${berat} kg<br>Poin: <b>+${poin}</b>${verifiedAt?`<br><br><span style="color:#666">Dicatat: ${verifiedAt} oleh ${adminNama||'Admin'}</span>`:''}`})}</script><?php include_once '../../includes/notif_scripts.php'; ?></body></html>
